<script lang="ts">
  import {onMount} from 'svelte';
  import Modal from './Modal.svelte';
  import {api,type ConflictDetails} from './api';
  let {repoId,file,onclose,onsaved,expected=null}:{repoId:number;file:string;onclose:()=>void;onsaved:()=>void;expected?:{branch:string;head:string|null}|null}=$props();
  let data=$state<ConflictDetails|null>(null);let content=$state('');let error=$state('');let busy=$state(false);let deleteConfirm=$state(false);let alive=true;
  onMount(()=>{void api.conflict(repoId,file).then(value=>{if(alive){data=value;content=value.current;}}).catch(e=>{if(alive)error=String(e);});return()=>{alive=false;};});
  async function save(remove=false){if(!data||busy)return;if(remove&&!deleteConfirm){deleteConfirm=true;return;}busy=true;error='';try{await api.git(repoId,remove?'resolve_delete':'resolve_file',remove?[file,data.current]:[file,content,data.current],expected);onsaved();onclose();}catch(e){error=String(e);}finally{busy=false;}}
</script>
<Modal canClose={!busy} label="Resolve conflict" {onclose}><div class="modal-top"><div><h2>Resolve conflict</h2><p class="conflict-path">{file}</p></div></div>{#if error}<p class="connection-error" role="alert">{error}</p>{/if}{#if data}<div class="conflict-sides"><section><h3>Current side</h3><pre>{data.ours??'File deleted on this side'}</pre><button class="secondary" disabled={busy||data.ours===null} onclick={()=>content=data!.ours!}>Use current</button></section><section><h3>Incoming side</h3><pre>{data.theirs??'File deleted on this side'}</pre><button class="secondary" disabled={busy||data.theirs===null} onclick={()=>content=data!.theirs!}>Use incoming</button></section></div><label for="resolved-content">Resolved contents</label><textarea id="resolved-content" class="conflict-result" rows="12" bind:value={content} disabled={busy} spellcheck="false"></textarea>{#if deleteConfirm}<p class="connection-error">This will delete the working file and stage that deletion as the conflict resolution.</p>{/if}<div class="modal-actions">{#if data.ours===null||data.theirs===null}<button class="dangerous secondary" disabled={busy} onclick={()=>save(true)}>{deleteConfirm?'Confirm deletion & stage':'Keep deletion'}</button>{/if}<button class="secondary" disabled={busy} onclick={onclose}>Cancel</button><button class="primary" disabled={busy} onclick={()=>save()}>Save & stage</button></div>{:else if !error}<p role="status">Loading conflict…</p>{:else}<div class="modal-actions"><button class="secondary" onclick={onclose}>Close</button></div>{/if}</Modal>
